var errorCatalogue = map[ErrorCode]ErrorInfo{
	CodeInvalidUTF8:             {CategorySyntax, "The input is not valid UTF-8 (§4): a byte sequence that encodes no character, an overlong form or a surrogate. Also an unpaired surrogate in a string of the language (UTF-16) given to a parser instead of bytes.", "Save the file as UTF-8."},
	CodeVersionDirective:        {CategorySyntax, "The file starts with a `#haus` version directive (§10): it was written for a later, incompatible version of haus.", "Read the file with a version of haus that supports it."},
	CodeExpectedValue:           {CategorySyntax, "A value is missing: after a key's colon, between commas, or at the start of a file, something else comes where a value must be, also a closing bracket (`[}`, `]`, `1,]`). After a key's colon the end of the input is this error too; anywhere else inside a bracket it is `unclosed-bracket`.", "Write a value here, or remove the extra comma or bracket."},
	CodeMissingComma:            {CategorySyntax, "Two values, fields or top-level values follow each other without a comma between them.", "Add a comma between the two values."},
	CodePayloadNewline:          {CategorySyntax, "A tag is followed by `(` or `{` on a later line, or after a comment. A payload must start on the tag's line (§5), so the two are read as separate values, and a comma is missing between them.", "Put the payload on the tag's line, or add a comma if they are two values."},
	CodeUnexpectedCloser:        {CategorySyntax, "A closing bracket after a value that doesn't match the open one (`[1}`), or that has no open one (`{ a: 1 }}`). Where a value or key is expected, a closing bracket is `expected-value` or `expected-key`.", "Close each bracket with its own kind (`{` `}`, `[` `]`, `(` `)`) and remove extra closing brackets."},
	CodeUnclosedBracket:         {CategorySyntax, "A `{`, `[` or `(` is never closed: the input ends first (`[1,`, `Some(`), except right after a key's colon, where it is `expected-value`.", "Add the closing bracket."},
	CodeNullLiteral:             {CategorySyntax, "`null` is not a value: haus has no null (§1).", "Write `None` (with a `Maybe` type), or leave the field out."},
	CodeBooleanLiteral:          {CategorySyntax, "`true` and `false` are not values: booleans are the tags `True` and `False` (§1).", "Write `True` or `False`."},
	CodeBareIdentifier:          {CategorySyntax, "A lowercase word where a value should be. Lowercase identifiers are only record keys.", "Quote it as a string, or start it with a capital letter to make it a tag."},
	CodeExpectedKey:             {CategorySyntax, "Something that can't be a record key where a key should be, such as a number or a comma.", "Write a key: a lowercase identifier or a string."},
	CodeUppercaseKey:            {CategorySyntax, "A record key starts with a capital letter. Bare keys start with a lowercase letter or `_`; capitalized words are tags.", "Quote the key, or start it with a lowercase letter."},
	CodeBlockStringKey:          {CategorySyntax, "A block string (`\"\"\"`) is used as a record key.", "Write the key as a basic string, `\"…\"`."},
	CodeMissingColon:            {CategorySyntax, "A record key is not followed by `:`.", "Add `:` between the key and its value."},
	CodeDuplicateKey:            {CategorySyntax, "A record has the same key twice, after escapes are read (`a` and `\"a\"` are the same key). Also a JSON object with the same member name twice (§16), and a record built in code with a key twice, rejected when it is built or, at the latest, when it is written, canonicalised or hashed (§11).", "Remove or rename one of the two."},
	CodeEmptyPayload:            {CategorySyntax, "A tag with empty parentheses, `Tag()`. A tag without arguments is written without them.", "Remove the empty parentheses after the tag."},
	CodeInvalidNumber:           {CategorySyntax, "A number literal that doesn't follow the grammar (§3): a leading zero, a `+`, a `.` without digits on both sides, a misplaced `_`, an uppercase `0X`, digits followed by letters. Also a string that should hold a number literal and doesn't (a `Decimal` in schema-based JSON, §16.3), and a number built in code whose text isn't a literal (`01`, `NaN`), rejected when it is built or, at the latest, when it is written, canonicalised or hashed (§11).", "Write a decimal number (optional `-`, fraction and exponent) or a hex or binary integer, with `_` only between digits."},
	CodeUnterminatedString:      {CategorySyntax, "A string has no closing `\"` (in haus or JSON).", "Add the closing quote. A quote inside the string is written `\\\"`."},
	CodeStringLineBreak:         {CategorySyntax, "A raw line break inside a `\"…\"` string.", "Write the line break as `\\n`, or use a `\"\"\"` block string."},
	CodeControlCharacter:        {CategorySyntax, "A raw control character (C0, DEL, C1) in a string, block string or comment, where it could change what a terminal shows. A raw tab is allowed in block strings and comments, not in `\"…\"` strings. Also a raw control character in a JSON string: C0 in any JSON, DEL and C1 in self-describing JSON (§16).", "Write the character as an escape, `\\u{…}`."},
	CodeBidiControl:             {CategorySyntax, "A raw bidirectional control character (U+202A–U+202E, U+2066–U+2069) in a string or comment, or in a self-describing JSON string (§16), where it could reorder how the text is displayed (\"Trojan Source\", §9).", "Write it as an escape (`\\u{…}`) inside a string, or remove it."},
	CodeInvalidEscape:           {CategorySyntax, "A backslash followed by a character that doesn't start an escape, or by the end of the input. haus has `\\\"`, `\\\\`, `\\n`, `\\r`, `\\t` and `\\u{…}`; JSON has its own set.", "Use one of the escapes of §4, or write `\\\\` for a backslash."},
	CodeInvalidUnicodeEscape:    {CategorySyntax, "A `\\u` escape that isn't `\\u{` 1 to 6 hex digits `}`, or names no Unicode scalar value (a surrogate, or above 10FFFF). In JSON: `\\u` not followed by four hex digits.", "Write the escape with braces, `\\u{…}`, for a character from U+0000 to U+10FFFF other than a surrogate."},
	CodeBlockStringOpening:      {CategorySyntax, "Text after the opening `\"\"\"` of a block string, or the end of the input right after it. The content starts on the next line.", "Start the content on the line after `\"\"\"`."},
	CodeBlockStringClosing:      {CategorySyntax, "The closing `\"\"\"` of a block string has text before it on its line.", "Put the closing `\"\"\"` on its own line; its indentation is removed from every line."},
	CodeBlockStringIndent:       {CategorySyntax, "A line of a block string is indented less than the closing `\"\"\"`, whose indentation every line must start with.", "Indent every line at least as far as the closing `\"\"\"`."},
	CodeUnterminatedBlockString: {CategorySyntax, "A block string has no closing `\"\"\"`.", "Add the closing `\"\"\"` on its own line."},
	CodeUnterminatedBytes:       {CategorySyntax, "A byte string `x\"…` has no closing `\"`.", "Add the closing quote."},
	CodeBytesNotHex:             {CategorySyntax, "A byte string holds something other than hex digits, spaces and tabs, such as a letter after `f`, an escape or a line break, where a byte starts. After a byte's first digit, anything but a second one is `bytes-odd-digits`.", "Write two hex digits per byte, on one line."},
	CodeBytesOddDigits:          {CategorySyntax, "A byte in a byte string has only one hex digit: an odd number of digits, or anything but a second hex digit after the first (a space, a letter after `f`, a line break: `x\"az\"`).", "Write each byte as two hex digits."},
	CodeLoneCarriageReturn:      {CategorySyntax, "A carriage return (CR) not followed by a line feed. Line breaks are LF or CRLF.", "Save the file with LF or CRLF line endings."},
	CodeUnterminatedComment:     {CategorySyntax, "A `/*` comment is never closed. Block comments nest, so each `/*` needs its own `*/`.", "Add `*/`, one for each `/*`."},
	CodeStraySlash:              {CategorySyntax, "A `/` that doesn't start a comment. Comments are `//` and `/* */`; haus has no operators.", "Write `//` or `/*` for a comment, or remove the `/`."},
	CodeNestingTooDeep:          {CategoryLimits, "Records, arrays and payloads are nested deeper than the depth limit (default 256). In JSON, deeper than its JSON limit (§16).", "Flatten the data, or raise the depth limit if you trust the input."},
	CodeNumberTooLong:           {CategoryLimits, "A number literal has more characters than the limit (default 1000), or a hex literal more hex digits than the number limit allows (default 829), so that every integer fits the limit in decimal (§7). A writer measures a number built in code on its normalized literal (§11); one over both the number and the exponent limit may fail with either code.", "Write a shorter number (a `String` or `Bytes` for very long data), or raise the number length limit."},
	CodeExponentTooLarge:        {CategoryLimits, "A number's exponent is larger than the limit (default 6144), in either direction. A writer measures a number built in code on its normalized literal (§11), as for `number-too-long`.", "Write a number with a smaller exponent, or raise the exponent limit."},
	CodeStringTooLong:           {CategoryLimits, "A string or byte string has more characters than the limit (default 16 Mi).", "Split the string, or raise the string length limit."},
	CodeKeyTooLong:              {CategoryLimits, "A record key has more characters than the string limit (default 16 Mi).", "Use a shorter key, or raise the string length limit."},
	CodeTagTooLong:              {CategoryLimits, "A tag has more characters than the string limit (default 16 Mi).", "Use a shorter tag, or raise the string length limit."},
	CodeValueTooLong:            {CategoryLimits, "One top-level value of a haus stream has more characters than the limit (default 64 Mi). A line of JSON Lines has no such limit (§16).", "Send smaller values, or raise the value length limit."},
	CodeUnsupportedDepth:        {CategoryLimits, "The configured depth limit is above the deepest nesting the binding supports, or isn't a whole number (§7). Raised when the limits are set, not by any input.", "Configure a depth limit within the binding's documented maximum."},
	CodeNotOneValue:             {CategoryStreams, "One value was expected (a single document, a type that isn't a `Stream`), and the input holds none or several.", "Give exactly one value, or read the input as a stream."},
	CodeStreamTruncated:         {CategoryStreams, "In strict mode, a stream ended without a comma (or, in JSON Lines, a line feed) after its last value, so the last value may be cut off (§6).", "End every value with a comma, or check that the stream wasn't cut off."},
	CodeSchemaSyntax:            {CategorySchemaFiles, "A schema file doesn't follow the grammar: an unexpected token, a character that has no place there. Mistakes in the comments, whitespace and strings a schema file shares with data files (§14) have the codes they have there: `unterminated-string`, `unterminated-comment`, `lone-carriage-return`, `control-character`, `bidi-control`, `invalid-utf8`, `invalid-escape`.", "Write it as the grammar says (grammar.ebnf); the message names what was expected."},
	CodeUnknownType:             {CategorySchemaFiles, "A type name that is neither defined in the file, imported, nor a prelude type. A type a standard module or official extension has needs its import.", "Define the type, fix its spelling, or import it from the module that defines it."},
	CodeWrongArity:              {CategorySchemaFiles, "A type is used with the wrong number of arguments: `Array` without its element type, `Int` with one, a generic type of your own with too few or too many.", "Give the type exactly as many arguments as it has parameters."},
	CodeDuplicateType:           {CategorySchemaFiles, "Two definitions of the same type name, or a definition with the name of an imported type.", "Rename one of them."},
	CodeRedefinePrelude:         {CategorySchemaFiles, "A definition with the name of a prelude type (`Int`, `Any`, `Secret`, `Maybe`, …), which schemas can't redefine.", "Give your type another name."},
	CodeUnknownParameter:        {CategorySchemaFiles, "A lowercase name in a type that is not a parameter of the definition.", "Declare the parameter after the type's name, or use a type name."},
	CodeInvalidParameter:        {CategorySchemaFiles, "A type parameter starting with `_`, or the same parameter twice in one definition.", "Give each parameter its own lowercase name."},
	CodeUnderscoreType:          {CategorySchemaFiles, "`_` used as a type. Types are open by default, so there is no wildcard.", "Write `< >` for a variant with any tags, `Any` for any value, or use a type parameter."},
	CodeDuplicateField:          {CategorySchemaFiles, "A record type lists the same field twice, also one copied in by a spread.", "Remove or rename one of them."},
	CodeDuplicateTag:            {CategorySchemaFiles, "A variant type lists the same tag twice, also one copied in by a spread.", "Remove or rename one of them."},
	CodeClosedEmptyVariant:      {CategorySchemaFiles, "`closed < >`: a closed variant without tags accepts nothing. Checked as written: `closed < ...E >` is accepted even when `E` has no tags.", "List its tags, or write `< >` for a variant with any tags."},
	CodeInvalidSpread:           {CategorySchemaFiles, "A spread of something that can't be spread: not a named type, a type with parameters, a `Stream`, a type of the prelude (`...Bool`), or a record spread into a variant (or a variant into a record). An alias or a generic instance is spread as what it stands for.", "Spread a named variant into a variant, or a named record into a record, without parameters."},
	CodeSpreadCycle:             {CategorySchemaFiles, "A type spreads itself, directly or through other types.", "Break the cycle: let one of the types list its tags or fields itself."},
	CodeRowParameter:            {CategorySchemaFiles, "A spread of a parameter, `...r`. Row parameters are not part of the language.", "Spread a named type instead, or nest the open part as a field with a type parameter."},
	CodeMisplacedStream:         {CategorySchemaFiles, "`Stream` used anywhere but as the whole type of a definition, or a reference to such a definition. A stream is a whole file.", "Use `Array` inside types, and `Stream` only as the whole of a definition."},
	CodeUnguardedRecursion:      {CategorySchemaFiles, "A type refers to itself without a record field, array element or variant payload in between (§9.9), so decoding it would consume no input. `Secret` and names don't count as a step.", "Put the recursion inside a record field, array element or variant payload."},
	CodeGrowingRecursion:        {CategorySchemaFiles, "Generic types whose instances could grow without bound: a type parameter passes, wrapped in a bigger type, along a cycle of references back to itself (`type T a = < X (T (Pair a a)) >`, §9.10).", "Refer to the type inside itself with exactly its own parameters."},
	CodeTypeTooDeep:             {CategorySchemaFiles, "Type expressions are nested deeper than the schema parser's limit.", "Name the inner types with definitions of their own."},
	CodeAttributeArguments:      {CategorySchemaFiles, "An attribute this version defines, given arguments it doesn't take: `@deprecated` takes nothing or one string. Also empty parentheses after an attribute.", "Give the attribute only the arguments it takes: `@deprecated` takes none, or one string."},
	CodeAttributeTwice:          {CategorySchemaFiles, "The same attribute twice on one type, field or tag, for an attribute this version defines. One it doesn't define may appear twice, with a warning each (`unknown-attribute`).", "Keep one of them."},
	CodeAttributeSpace:          {CategorySchemaFiles, "A space between an attribute's name and its `(`.", "Write the parenthesis right after the attribute's name, without a space."},
	CodeAttributeOnSpread:       {CategorySchemaFiles, "An attribute on a spread. The fields and tags a spread copies keep their own attributes.", "Put the attribute on the fields or tags in the spread type."},
	CodeUnknownModule:           {CategoryImports, "An import of a module that doesn't exist: an unknown standard module, a former standard module, a package name that breaks npm's rules (`@Haus/money`), or a module that starts with `.` but not with `./` or `../` (`.../a`, `..`, `.x`). Any other word where a module belongs (`foo/bar`, `Lib/a-b`), and `.` alone, is `schema-syntax` (grammar.ebnf).", "Fix the module's name; a former standard module is now a package, which the message names."},
	CodeUnknownImport:           {CategoryImports, "An import names a type the module doesn't have, or no type at all.", "Import a type the module defines; the message lists them."},
	CodeDuplicateImport:         {CategoryImports, "The same type name is imported twice.", "Import each name once."},
	CodeImportUnavailable:       {CategoryImports, "The schema imports a package or file, and the tool reading it has no way to find one (no module resolver): only standard modules can be imported there.", "Read the schema with a resolver that loads imports (from files or packages), or inline the types."},
	CodeImportNotFound:          {CategoryImports, "An imported package or file can't be found: it is not installed, the path is wrong, the file is not a regular file (a directory, a FIFO, a device) or is spelled otherwise than its directory lists it, a directory on its way can't be listed, a name on a relative import's path is a symbolic link (which a relative import never follows), whether the file is in a package's directory can't be checked (a directory between it and the build's root can't be listed), or the package found names another package in its manifest. With npm, also a `node_modules/@org/name` that is there but can't be used (a dangling link, a cycle of links, a directory that can't be entered): the search stops there (§13.3).", "Install the package, or fix the path."},
	CodeImportOutsideRoot:       {CategoryImports, "A relative import reaches a file outside the build's root directory (§13.3): by default the directory of the schema file the build starts from, or the directory given as the build's `root` option. Its `..` names go above the root: it is rejected before anything is looked at (a relative import follows no symbolic link, so it can't leave the root otherwise). Also a `root` option that doesn't contain the schema file the build starts from.", "Give the build a `root` option that contains both files (such as the repository's schema directory), or move the shared file inside the root; publish types used across projects as a schema package."},
	CodeImportVersion:           {CategoryImports, "An import asks for a major version (`@org/name@2`) and another one is installed, or names something other than a major version: `@1.1`, `@1.1.0`, `@01`, `@x`, `@1~x`, `@1@2` (a package module is one token up to a blank or `(`, grammar.ebnf).", "Install the major version the schema asks for, or update the import. An import names only the major version (`@1`); the minimum minor goes in your package manager's dependency range."},
	CodeImportCycle:             {CategoryImports, "Schema files import each other in a cycle.", "Move the shared types to a file both import."},
	CodeDuplicatePackage:        {CategoryImports, "One schema reaches two different packages with the same name: two versions of one package (also two major versions), two copies of one version whose files differ, or two packages that call themselves the same. Byte-identical copies are one package.", "Install one copy of the package: align the version ranges and deduplicate (`npm dedupe`). On npm, declare schema packages a package imports as `peerDependencies`."},
	CodeUndeclaredPackage:       {CategoryImports, "A file imports a package that its package or project doesn't declare as a dependency (with npm: in the package's own `package.json`, or the nearest one above an application file), or a file with no `package.json` above it imports a package that wasn't given explicitly. A package found only because the package manager placed it nearby, such as a hoisted dependency of a dependency, could be replaced by another one placed there. Checked before the package is looked for.", "Add the package to the dependencies of the importing package or project (on npm, `peerDependencies` for a package). Outside an npm project, such as in a Cargo or Python project, give the package explicitly (`--package`, `--packages`, the editor's `haus.packages`, Python's `packages=`)."},
	CodePackageManifest:         {CategoryImports, "A package's `package.haus` is not a valid manifest: not one record, a `name` that isn't a lowercase `@org/name` (or has the part `node_modules`), a `version` that isn't a semantic version, or more than 64 KiB.", "Write `{ name: \"@org/name\", version: \"1.2.0\" }`, in lowercase, with a full version."},
	CodePackageVersion:          {CategoryImports, "A package's `package.haus` has another version than the package manager gives the package (the `version` of its `package.json`, its Cargo version). A check implementations SHOULD make (§13.3), also for a package given explicitly by its directory that has a `package.json` next to its manifest. A subdirectory of a folder of packages with such a version is skipped instead, like one with a broken manifest, and named when an import isn't found; a `package.json` beside a package given by its directory that can't be read is ignored, by every implementation.", "Release both with the same version: change them together."},
	CodePackagePath:             {CategoryImports, "A schema package refers to a file it may not: its `schema.haus` imports a file (`import ./x`) instead of a package; its `package.haus`, `schema.haus` or `package.json` is a symbolic link or not a regular file; or a file outside any package imports a file in a package's directory (`import ./node_modules/x/y`). The file is not read.", "A package is its `package.haus` and one `schema.haus`, and imports other packages by name (`import @org/name`); import a package by name from your own files too."},
	CodePackageName:             {CategoryImports, "A package manager's name for a schema package differs from its manifest's: the `name` of its `package.json` isn't the `name` of its `package.haus`. On npm, imports find a package by that name, so it must be the manifest's (§13.3). Reported by package checks such as `haus package check`.", "Publish the package under its manifest's name: make the `name` of `package.json` the same."},
	CodePackageCrate:            {CategoryImports, "A schema package's crate can't be named by the code generated for crates that use its types: its `links` is missing or isn't its library's name (`[lib] name`), or a crate depends on a schema package's crate under another name (`package = …`). Generated code names a schema package's crate by its `links`, which is its library's name. Reported by package checks such as `haus package check`.", "Set `links` to the library's name in `[package]`, and depend on schema package crates under their own names."},
	CodePackageInstallScript:    {CategoryImports, "A schema package runs code when it is installed: an npm `preinstall`, `install` or `postinstall` script, or a `binding.gyp`, for which npm runs node-gyp. A schema package is data and MUST NOT need code to install (§13.3).", "Remove the script: a schema package is its manifest, its schema and its profiles, and needs nothing run."},
	CodePackageFiles:            {CategoryImports, "A package manager's configuration doesn't ship a file of the schema package: `package.haus`, `schema.haus`, or a profile's vectors or rule. Read from the configuration (`files` of `package.json`, `include` of `Cargo.toml`, a wheel's build configuration), without packing anything.", "List `package.haus`, `schema.haus` and `profiles` in what the package manager ships."},
	CodeProfileVectors:          {CategoryImports, "A profile of a schema package is malformed (§13.3): it has no rule (`profiles/<name>.md`) next to its vectors; a vector isn't `Accept { type, value, output?, note? }` or `Reject { type, value, note? }` with string fields and no others (only an `Accept` has an `output`); its `type` isn't a type of the package without parameters; its `value` or `output` isn't one haus value; or an accepted value or its output isn't valid for its type, which a codec running after the schema can't accept. Also a profile name that isn't lowercase, and a vectors file with no vectors.", "Write the rule in `profiles/<name>.md`, and each vector as `Accept { type: \"T\", value: \"…\" }` or `Reject { type: \"T\", value: \"…\" }`, with values valid for `T`."},
	CodePackageWrapper:          {CategoryImports, "A package manager's file of a schema package can't be read as one: a `package.json` that isn't a JSON object or has no `name`, a `Cargo.toml` or `pyproject.toml` that isn't valid TOML, a `Cargo.toml` without `[package]`. Reported by package checks such as `haus package check`.", "Fix the file so that its package manager can read it."},
	CodeCodecUnreachable:        {CategoryImports, "A codec's type occurs where this binding can't apply the codec, such as the payload of a record case whose fields sit beside its tag in the host value. Decoding there with the default host type would silently differ from the other bindings (§13.4).", "Give the codec's type a place of its own (a field), or decode the outer type yourself; the message names where the type occurs."},
	CodeFileTooLarge:            {CategoryImports, "A schema file or a package's `package.json` is larger than the tool allows (1 MiB by default). It is not read.", "Split the schema into several files, or raise the limit if you trust the file."},
	CodeTooManyFiles:            {CategoryImports, "A schema imports more schema files, directly or not, than the tool allows (256 by default, the root included), or a folder of packages has more entries than allowed (4096).", "Import fewer files."},
	CodeTypeMismatch:            {CategoryDecoding, "A value of another kind than the type accepts: a string for an `Int`, an array for a record, a tag that isn't `True` or `False` for a `Bool`. Decoders never convert between kinds (§15).", "Write a value of the expected type; the message says which."},
	CodeNotAnInteger:            {CategoryDecoding, "A number with a fraction or an exponent where an integer type is expected. `1.0` and `1e3` are not whole numbers by spelling (§15).", "Write the integer without a fraction or exponent."},
	CodeOutOfRange:              {CategoryDecoding, "A number outside the type's range: an `Int8` above 127, a negative `UInt32`, a float too large for `Float32`. Never wrapped or clamped.", "Write a value within the range, or use a larger type (`Int`, `Float64`, `Decimal`)."},
	CodeMissingField:            {CategoryDecoding, "A record lacks a field the type requires. Only fields with `?` may be missing; `None` is not missing.", "Add the field, or mark it optional in the schema with `?` after its name."},
	CodeUnknownField:            {CategoryDecoding, "A field a closed record doesn't list. Open records ignore such fields (see `unlisted-field`).", "Remove the field, fix its spelling, or add it to the schema."},
	CodeUnknownTag:              {CategoryDecoding, "A tag a closed variant doesn't list. Open variants read it as an unknown value (see `unlisted-tag`).", "Use one of the variant's tags, fix the spelling, or add the tag to the schema."},
	CodeWrongPayload:            {CategoryDecoding, "A listed tag with another payload than its case says: arguments for a tag without payload, the wrong number of arguments, a positional payload where a record is expected, such as `Circle(1.5)` for the case `Circle { r: Float64 }` (§15).", "Write the payload the schema gives the tag: none, one record, or its positional arguments; the message says which."},
	CodeInvalidTime:             {CategoryDecoding, "A std/time value whose text the std/time profile rejects: a day that doesn't exist, a missing offset, a lowercase `t` (spec/std/time.md).", "Write the date or time as the std/time profile says (spec/std/time.md); the message names the type."},
	CodeInvalidSecret:           {CategoryDecoding, "A value of a `Secret` type that its type doesn't accept, when decoding, or that can't be written, when encoding. The error names the place and the type only, never the value or why it failed (§15).", "Write a value of the secret's type; the value isn't shown, so check it where it comes from."},
	CodeCodecRejected:           {CategoryDecoding, "A value its type's schema accepts and a codec rejects (§13.4), such as an amount whose currency isn't in ISO 4217 for the `@haus-fmt/money/iso` profile. At the place of the codec's type.", "Write a value the codec accepts; the profile's rule (profiles/<name>.md) or the codec's documentation says which."},
	CodeCannotEncode:            {CategoryDecoding, "Encoding: a value of the program's language that the type can't write, such as a JavaScript number for an `Int` that expects a bigint, or a string that is no valid `Date`, or a host value a codec rejects (§13.4). Building a value in code (§11): a string or key with an unpaired surrogate, which has no UTF-8 form, or, in a binding whose strings are bytes, one that isn't valid UTF-8; or something that is no haus value (an object of another type where a value or a number is expected). Rejected when the value is built or, at the latest, when it is written, canonicalised or hashed.", "Pass a value of the host type the binding documents for the type."},
	CodeCyclicValue:             {CategoryDecoding, "Encoding: a value contains itself, so it has no finite text.", "Break the cycle before encoding."},
	CodeStepBudget:              {CategoryDecoding, "Decoding or encoding took more steps than the input justifies, a sign of a schema doing unbounded work. Bindings MUST bound the work of one decode (§9.8).", "Simplify the schema, or raise the step limit if the work is expected."},
	CodeTooManyNodes:            {CategoryDecoding, "A value built in code (not parsed) would write more values than the node limit allows (default 64 Mi, §7): its parts share each other so much that it expands when written, counted as writers, the canonical form and hashing write it.", "Build a smaller value, or raise the limit."},
	CodeJSONSyntax:              {CategoryJson, "Text that isn't JSON (RFC 8259): a missing comma or colon, an unquoted name, a trailing comma, a comment, text after the value. Also an empty line in JSON Lines, or a byte order mark at the start of a line after the first. A string that isn't closed, and a bad escape, have the codes of haus text: `unterminated-string`, `invalid-escape`, `invalid-unicode-escape`.", "Write valid JSON; the message says what was expected."},
	CodeUnpairedSurrogate:       {CategoryJson, "A JSON string with half of a UTF-16 surrogate pair, raw or as `\\uD800`. I-JSON forbids them, and they are no Unicode characters (§16).", "Write both halves of the surrogate pair, or the character itself."},
	CodeHausJSONForm:            {CategoryJson, "JSON that isn't self-describing JSON (§16.2): a text without the envelope `{\"_haus\": 1, \"_value\": …}`, an envelope with other members, a bare number, `true`, `null`, an object with other members, a `_rec` that isn't an object, an `_args` that isn't a non-empty array.", "Write the envelope with one of the forms of §16.2 in `_value`: a string, an array, or an object with `_num`, `_bytes`, `_rec`, or `_tag` (and `_args`). For ordinary JSON, read it with a schema or import it instead."},
	CodeHausJSONVersion:         {CategoryJson, "A self-describing JSON envelope whose `_haus` isn't 1, the only version of the form (§16.2): it was written for a later version of haus, or isn't haus.", "Read it with a newer version of haus, or write `\"_haus\": 1`."},
	CodeHausJSONNumber:          {CategoryJson, "A self-describing `_num` that isn't a normalized number literal (§2): `\"1E5\"`, `\"01\"`, `\"0xff\"`, or not a string.", "Write the number's normalized literal (§2) as a string."},
	CodeHausJSONBytes:           {CategoryJson, "A self-describing `_bytes` that isn't two lowercase hex digits per byte.", "Write the bytes as lowercase hex, two digits per byte."},
	CodeInvalidTag:              {CategoryJson, "A tag name that isn't `[A-Z][A-Za-z0-9_]*`, or a `\"_tag\"` that isn't a string: in a `_tag` of either JSON form, in the string of a closed variant whose tags have no payload in schema-based JSON (`\"debug\"`, §16.3), or in a value built in code (rejected when it is built or, at the latest, when it is written, canonicalised or hashed, §11), a tag with an unpaired surrogate included.", "Start the tag with a capital letter and use only letters, digits and `_`."},
	CodeInvalidBase64:           {CategoryJson, "Schema-based JSON `Bytes` that aren't canonical base64 with padding (RFC 4648 §4): whitespace, the URL alphabet, missing padding, non-zero pad bits.", "Write standard base64, with padding."},
	CodeMissingMember:           {CategoryJson, "Schema-based JSON: an object lacks a member its form needs, such as `\"_tag\"` for a variant or `\"value\"` for a tag with one argument.", "Add the member the message names."},
	CodeUnexpectedMember:        {CategoryJson, "Schema-based JSON: an object has a member its form doesn't have, such as `\"value\"` next to a tag without payload (§16.3).", "Remove the member."},
	CodeNoJSONForm:              {CategoryJson, "A value or type that has no JSON form: a string with an unpaired surrogate, a record payload with a field named `_tag` or `_args` in schema-based JSON (§16.3), a type with no schema-based form.", "Rename the field, or use self-describing JSON."},
	CodeUnknownAttribute:        {CategoryHints, "A warning: an attribute this version of haus doesn't define. It is accepted and has no meaning (§14).", "Check the spelling; attributes of a later version are fine."},
	CodeDeprecated:              {CategoryHints, "A hint: the schema or the data uses a type, field or tag marked `@deprecated` (§14).", "Use what the deprecation note says instead."},
	CodeUnlistedField:           {CategoryHints, "A hint: a field an open record doesn't list. A reader ignores it, but it may be a typo.", "Fix the spelling, add the field to the schema, or leave it if it is meant for newer readers."},
	CodeUnlistedTag:             {CategoryHints, "A hint: a tag an open variant doesn't list. A reader keeps it as an unknown value, but it may be a typo.", "Fix the spelling, add the tag to the schema, or leave it if it is meant for newer readers."},
	CodeMissingCodec:            {CategoryHints, "A warning: the schema reaches a type that an official profile has a rule for (`@haus-fmt/money@1#Currency`, `@haus-fmt/geo@1#LatLng`, `@haus-fmt/geo@1#BBox`, `@haus-fmt/uuid@1#Uuid`), and no codec is set for it, so the rule is not checked: its values are checked for their shape only (§13.4). Decoding is unchanged. Tools without codecs (`haus check`, editors) report it as a note, once per import of such a package.", "Add the codec of the profile your application uses (`iso` from `@haus-fmt/money`), or your own codec for the type."},
	CodeUnusedCodec:             {CategoryHints, "A warning: a codec is set for an id that no type has (§13.4): not a type of the prelude or a standard module, nor of the schema's files and the packages they import. It never runs, so the values it was meant to check pass unchecked. Decoding is unchanged.", "Fix the codec's id: the package's name and major version, and the type's name, as the schema imports them."},
}
